#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    int earliestFinishTime(std::vector<int>& landStartTime, std::vector<int>& landDuration, std::vector<int>& waterStartTime, std::vector<int>& waterDuration) {
        int min_l_finish = INT_MAX;
        for (size_t i = 0; i < landStartTime.size(); ++i) {
            min_l_finish = std::min(min_l_finish, landStartTime[i] + landDuration[i]);
        }

        int min_w_finish = INT_MAX;
        for (size_t j = 0; j < waterStartTime.size(); ++j) {
            min_w_finish = std::min(min_w_finish, waterStartTime[j] + waterDuration[j]);
        }

        int best_lw = INT_MAX;
        for (size_t j = 0; j < waterStartTime.size(); ++j) {
            int finish = std::max(min_l_finish, waterStartTime[j]) + waterDuration[j];
            best_lw = std::min(best_lw, finish);
        }

        int best_wl = INT_MAX;
        for (size_t i = 0; i < landStartTime.size(); ++i) {
            int finish = std::max(min_w_finish, landStartTime[i]) + landDuration[i];
            best_wl = std::min(best_wl, finish);
        }

        return std::min(best_lw, best_wl);
    }
};

import java.util.*;

class Solution {
    public int earliestFinishTime(int[] landStartTime, int[] landDuration, int[] waterStartTime, int[] waterDuration) {
        int minLFinish = Integer.MAX_VALUE;
        for (int i = 0; i < landStartTime.length; i++) {
            minLFinish = Math.min(minLFinish, landStartTime[i] + landDuration[i]);
        }

        int minWFinish = Integer.MAX_VALUE;
        for (int j = 0; j < waterStartTime.length; j++) {
            minWFinish = Math.min(minWFinish, waterStartTime[j] + waterDuration[j]);
        }

        int bestLW = Integer.MAX_VALUE;
        for (int j = 0; j < waterStartTime.length; j++) {
            int finish = Math.max(minLFinish, waterStartTime[j]) + waterDuration[j];
            bestLW = Math.min(bestLW, finish);
        }

        int bestWL = Integer.MAX_VALUE;
        for (int i = 0; i < landStartTime.length; i++) {
            int finish = Math.max(minWFinish, landStartTime[i]) + landDuration[i];
            bestWL = Math.min(bestWL, finish);
        }

        return Math.min(bestLW, bestWL);
    }
}

